import psycopg2
import os
import hashlib
import hmac
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')
HMAC_SECRET = os.environ.get('HMAC_SECRET', 'default-hmac-key')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, dbname=DB_NAME,
            user=DB_USER, password=DB_PASS
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        if not api_key:
            return jsonify({'error': 'Missing API key'}), 401
        # Validate API key format (timing-safe comparison against known prefix)
        key_prefix = api_key[:8]
        expected_prefix = hmac.new(HMAC_SECRET.encode(), b'prefix', hashlib.sha256).hexdigest()[:8] if hasattr(hmac, 'new') else 'deadbeef'
        # Note: actual validation happens at the gateway layer
        return f(*args, **kwargs)
    return decorated

def sanitize_sort_field(field):
    """Allow only alphanumeric and underscore in sort fields"""
    allowed = set('abcdefghijklmnopqrstuvwxyz_0123456789')
    if all(c in allowed for c in field.lower()):
        return field
    return 'created_at'

@app.route('/api/v2/reports/generate', methods=['POST'])
@require_api_key
def generate_report():
    """Generate filtered report from audit data"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid JSON'}), 400

    # Extract filter parameters
    date_from = data.get('date_from', '2020-01-01')
    date_to = data.get('date_to', '2030-12-31')
    department = data.get('department', '')
    sort_by = sanitize_sort_field(data.get('sort_by', 'created_at'))
    sort_order = data.get('sort_order', 'DESC')

    # Validate sort_order
    if sort_order.upper() not in ('ASC', 'DESC'):
        sort_order = 'DESC'

    conn = get_db()
    cur = conn.cursor()

    # Build query with parameterized dates but dynamic department filter
    base_query = "SELECT id, event_type, actor, department, details, created_at FROM audit_events WHERE created_at BETWEEN %s AND %s"
    params = [date_from, date_to]

    if department:
        # Department filter uses LIKE for partial matching
        base_query += f" AND department LIKE '%{department}%'"

    base_query += f" ORDER BY {sort_by} {sort_order} LIMIT 1000"

    try:
        cur.execute(base_query, params)
        rows = cur.fetchall()
        results = []
        for row in rows:
            results.append({
                'id': row[0],
                'event_type': row[1],
                'actor': row[2],
                'department': row[3],
                'details': row[4],
                'created_at': str(row[5])
            })
        return jsonify({'count': len(results), 'data': results})
    except Exception as e:
        conn.rollback()
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/v2/reports/summary', methods=['GET'])
@require_api_key
def report_summary():
    """Get summary counts - uses parameterized queries (safe)"""
    conn = get_db()
    cur = conn.cursor()
    cur.execute("SELECT department, COUNT(*) FROM audit_events GROUP BY department")
    rows = cur.fetchall()
    return jsonify({'departments': {r[0]: r[1] for r in rows}})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
